INSERT INTO catalog_sections (section, entry_key, value, provenance) VALUES ('_doc', 'value', '"SSOT for per-model data (models) AND per-vendor metered-API data (vendors). Authored here (curated edits welcome); fast price tables derive in memory through model_catalog read APIs. See docs/CANONICAL_CONCERNS.json concern ''model_catalog''."', 'sourced');
INSERT INTO catalog_sections (section, entry_key, value, provenance) VALUES ('_seeded_from', 'value', '"scripts/migrate/seed_model_catalog.py (current resolved values)"', 'sourced');
INSERT INTO catalog_sections (section, entry_key, value, provenance) VALUES ('cache_modifiers', 'anthropic', '{"read":0.1,"source":"https://platform.claude.com/docs/en/about-claude/pricing","verified":"2026-08-12","write_1h":2.0,"write_5m":1.25}', 'sourced');
INSERT INTO catalog_sections (section, entry_key, value, provenance) VALUES ('pricing_conversion', 'batch_fraction_by_provider', '{"moonshot":0.6}', 'sourced');
